package io.mavsdk.kotlin.plugins.info

import io.mavsdk.kotlin.System
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

/** Provide information about the hardware and/or software of a system. */
class Info internal constructor(private val native: InfoNative) : AutoCloseable {
    private var closed = false

    /** Possible results returned for info requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Information has not been received yet */
        INFORMATION_NOT_RECEIVED_YET(2),
        /** No system is connected */
        NO_SYSTEM(3);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /** These values define the type of firmware/flight software release */
    enum class FlightSoftwareVersionType(val value: Int) {
        /** Unknown type */
        UNKNOWN(0),
        /** Development release */
        DEV(1),
        /** Alpha release */
        ALPHA(2),
        /** Beta release */
        BETA(3),
        /** Release candidate */
        RC(4),
        /** Official stable release */
        RELEASE(5);

        companion object {
            fun fromValue(value: Int): FlightSoftwareVersionType =
                entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * System flight information.
     *
     * @property timeBootMs Time since system boot
     * @property flightUid Flight counter. Starts from zero, is incremented at every disarm and is
     *   never reset (even after reboot)
     * @property durationSinceArmingMs Duration since arming in milliseconds
     * @property durationSinceTakeoffMs Duration since takeoff in milliseconds
     */
    data class FlightInfo(
        val timeBootMs: Int,
        val flightUid: Long,
        val durationSinceArmingMs: Int,
        val durationSinceTakeoffMs: Int,
    )

    /**
     * System identification.
     *
     * @property hardwareUid UID of the hardware. This refers to uid2 of MAVLink. If the system does
     *   not support uid2 yet, this is all zeros.
     * @property legacyUid Legacy UID of the hardware, referred to as uid in MAVLink (formerly
     *   exposed during system discovery as UUID).
     */
    data class Identification(val hardwareUid: String, val legacyUid: Long)

    /**
     * System product information.
     *
     * @property vendorId ID of the board vendor
     * @property vendorName Name of the vendor
     * @property productId ID of the product
     * @property productName Name of the product
     */
    data class Product(
        val vendorId: Int,
        val vendorName: String,
        val productId: Int,
        val productName: String,
    )

    /**
     * System version information.
     *
     * @property flightSwMajor Flight software major version
     * @property flightSwMinor Flight software minor version
     * @property flightSwPatch Flight software patch version
     * @property flightSwVendorMajor Flight software vendor major version
     * @property flightSwVendorMinor Flight software vendor minor version
     * @property flightSwVendorPatch Flight software vendor patch version
     * @property osSwMajor Operating system software major version
     * @property osSwMinor Operating system software minor version
     * @property osSwPatch Operating system software patch version
     * @property flightSwGitHash Flight software git hash
     * @property osSwGitHash Operating system software git hash
     * @property flightSwVersionType Flight software version type
     */
    data class Version(
        val flightSwMajor: Int,
        val flightSwMinor: Int,
        val flightSwPatch: Int,
        val flightSwVendorMajor: Int,
        val flightSwVendorMinor: Int,
        val flightSwVendorPatch: Int,
        val osSwMajor: Int,
        val osSwMinor: Int,
        val osSwPatch: Int,
        val flightSwGitHash: String,
        val osSwGitHash: String,
        val flightSwVersionType: FlightSoftwareVersionType,
    )

    /**
     * Get the identification of the system.
     *
     * @return Identification of the system
     */
    fun getIdentification(): Identification = native.getIdentification()

    /**
     * Get product information of the system.
     *
     * @return Product information of the system
     */
    fun getProduct(): Product = native.getProduct()

    /**
     * Get the version information of the system.
     *
     * @return Version information about the system
     */
    fun getVersion(): Version = native.getVersion()

    /**
     * Get the speed factor of a simulation (with lockstep a simulation can run faster or slower
     * than realtime).
     *
     * @return Speed factor of simulation
     */
    fun getSpeedFactor(): Double = native.getSpeedFactor()

    /**
     * Subscribe to 'flight information' updates.
     *
     * @return The next flight information
     */
    fun subscribeFlightInformation(): Flow<FlightInfo> = callbackFlow {
        val subscriptionHandle = native.subscribeFlightInformation() { value -> trySend(value) }
        awaitClose { native.unsubscribeFlightInformation(subscriptionHandle) }
    }

    override fun close() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class InfoException(val result: Result, message: String) : Exception(message)

    companion object {
        fun create(system: System): Info =
            Info(createInfoNative(system.getHandle())).also { system.registerPlugin(it) }
    }
}

internal interface InfoNative {
    fun getIdentification(): Info.Identification

    fun getProduct(): Info.Product

    fun getVersion(): Info.Version

    fun getSpeedFactor(): Double

    fun subscribeFlightInformation(callback: (Info.FlightInfo) -> Unit): Long

    fun unsubscribeFlightInformation(subscriptionHandle: Long)

    fun destroy()
}

internal expect fun createInfoNative(systemHandle: Long): InfoNative
